from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and extract each group of nested parentheses
    groups = []
    current_group = ""
    open_braces = 0

    for char in paren_string:
        if char == "(":
            open_braces += 1
        elif char == ")":
            open_braces -= 1

        current_group += char

        if open_braces == 0:
            groups.append(current_group)
            current_group = ""

    # Step 3: Check if each group is balanced (properly closed)
    balanced_groups = []

    for group in groups:
        if group.count("(") == group.count(")"):
            balanced_groups.append(group)

    # Step 4: Ensure that separate groups are not nested within each other
    final_groups = []

    for i in range(len(balanced_groups)):
        is_nested = False

        for j in range(len(balanced_groups)):
            if i != j and balanced_groups[i] in balanced_groups[j]:
                is_nested = True
                break

        if not is_nested:
            final_groups.append(balanced_groups[i])

    # Step 5: Return the list of balanced and separate groups
    return final_groups
